// Fuelizer service worker — hand-written rather than generated by a
// webpack-based tool (e.g. next-pwa/Workbox), because this project builds
// with Turbopack, which does not run webpack plugins. Turbopack has no
// build-time hook to inject a precache manifest of hashed asset URLs, so
// this intentionally does NOT try to precache the JS/CSS bundle — instead
// it caches pages and static assets as they're actually requested
// (runtime caching), which needs no build-time integration at all.
//
// Bump this on any change to the caching logic below so old clients evict
// their caches instead of running stale strategies indefinitely.
const CACHE_VERSION = "v1";
const STATIC_CACHE = `fuelizer-static-${CACHE_VERSION}`;
const RUNTIME_CACHE = `fuelizer-runtime-${CACHE_VERSION}`;
const OFFLINE_URL = "/offline";

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(STATIC_CACHE).then((cache) => cache.addAll([OFFLINE_URL]))
  );
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((key) => key !== STATIC_CACHE && key !== RUNTIME_CACHE)
            .map((key) => caches.delete(key))
        )
      )
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Next.js's build output under /_next/static/ is content-hashed and
  // therefore immutable — safe to cache aggressively and serve instantly.
  if (url.pathname.startsWith("/_next/static/")) {
    event.respondWith(cacheFirst(request, STATIC_CACHE));
    return;
  }

  // Page navigations: prefer a fresh network response (this is a live app
  // with per-request data, not a static site), falling back to the last
  // cached copy of that page, and finally to a dedicated offline page.
  if (request.mode === "navigate") {
    event.respondWith(networkFirstNavigation(request));
  }
});

async function cacheFirst(request, cacheName) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  if (cached) return cached;

  const response = await fetch(request);
  if (response.ok) cache.put(request, response.clone());
  return response;
}

async function networkFirstNavigation(request) {
  const cache = await caches.open(RUNTIME_CACHE);
  try {
    const response = await fetch(request);
    if (response.ok) cache.put(request, response.clone());
    return response;
  } catch {
    const cached = await cache.match(request);
    if (cached) return cached;

    const offline = await caches.match(OFFLINE_URL);
    return offline ?? Response.error();
  }
}
